import re
def money(s):
    def f(x):
        if pd.isna(x): return 0.0
        if isinstance(x,(int,float)): return float(x)
        x=str(x).strip().lower().replace('đ','').replace('vnd','').replace(' ','')
        m=re.fullmatch(r'(\d+)tr(\d*)',x)
        if m:
            r=m.group(2); return int(m.group(1))*1e6+(int(r.ljust(3,'0')[:3])*1000 if r else 0)
        m=re.fullmatch(r'(\d+),(\d+)tr',x)
        if m: return float(m.group(1)+'.'+m.group(2))*1e6
        m=re.fullmatch(r'([\d,.]+)k',x)
        if m: return float(m.group(1).replace(',','.'))*1000
        if re.fullmatch(r'\d{1,3}(,\d{3})+(\.\d+)?',x): return float(x.replace(',',''))
        if re.fullmatch(r'\d{1,3}(\.\d{3})+',x): return float(x.replace('.',''))
        try: return float(x.replace(',',''))
        except: return float('nan')
    return s.map(f)
def pdate(s):
    def f(x):
        if pd.isna(x): return pd.NaT
        x=str(x).strip()
        if re.fullmatch(r'\d{5}(\.0)?',x): return pd.Timestamp('1899-12-30')+pd.Timedelta(days=int(float(x)))
        m=re.match(r'(\d{1,2}) thg (\d{1,2}) (\d{4})',x)
        if m: return pd.Timestamp(int(m.group(3)),int(m.group(2)),int(m.group(1)))
        m=re.match(r'(\d{1,2})/(\d{1,2})/(\d{4})',x)
        if m: return pd.Timestamp(int(m.group(3)),int(m.group(2)),int(m.group(1)))
        m=re.match(r'(\d{4})-(\d{2})-(\d{2})',x)
        if m: return pd.Timestamp(int(m.group(1)),int(m.group(2)),int(m.group(3)))
        return pd.NaT
    return s.map(f)

