        s = s.replace(',', '')
    elif s.endswith('k'):
        mult = 1000.0
        s = s[:-1]
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    else:
        s = s.replace(',', '').replace('.', '') if s.count('.') > 0 and s.count(',') > 0 else s.replace(',', '')
    s = re.sub('[^0-9.\\-]', '', s)
